package com.mycompany.rentalmanagement.dao;
import com.mycompany.rentalmanagement.DBConnection;import java.sql.*;import java.util.*;
public class CustomerDAO {
 public List<Map<String,Object>> list(String q)throws SQLException{List<Map<String,Object>> a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM customers WHERE full_name LIKE ? OR phone LIKE ? OR license_number LIKE ? OR COALESCE(email,'') LIKE ? ORDER BY id DESC")){for(int i=1;i<=4;i++)p.setString(i,DAOUtil.like(q));try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();for(String k:new String[]{"id","full_name","email","phone","license_number","address","active"})m.put(k,r.getObject(k));a.add(m);}}}return a;}
 public Map<String,Object> get(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM customers WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Map<String,Object> m=new LinkedHashMap<>();for(String k:new String[]{"id","full_name","email","phone","license_number","address","active"})m.put(k,r.getObject(k));return m;}}}
 public void save(long id,String name,String email,String phone,String license,String address)throws SQLException{if(id==0){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO customers(full_name,email,phone,license_number,address) VALUES(?,?,?,?,?)")){bind(p,name,email,phone,license,address);p.executeUpdate();}}else try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE customers SET full_name=?,email=?,phone=?,license_number=?,address=? WHERE id=?")){bind(p,name,email,phone,license,address);p.setLong(6,id);if(p.executeUpdate()==0)throw new SQLException("Customer not found.");}}
 private void bind(PreparedStatement p,String n,String e,String ph,String l,String a)throws SQLException{p.setString(1,n);p.setString(2,e.isBlank()?null:e);p.setString(3,ph);p.setString(4,l);p.setString(5,a);}
 public void deactivate(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE customers SET active=0 WHERE id=? AND NOT EXISTS(SELECT 1 FROM rentals r WHERE r.customer_id=customers.id AND r.status IN ('BOOKED','ACTIVE'))")){p.setLong(1,id);if(p.executeUpdate()==0)throw new SQLException("Customer has an active rental/booking or was not found; cannot deactivate.");}}
}
